      "type": "text",
      "runs": [
        {
          "text": "A Kubernetes Deployment replaces pods incrementally while the active Service keeps routing across old and new replicas, so spare capacity remains low relative to blue-green or canary and is governed by maxSurge and maxUnavailable.",
          "bullet": false
